import { useState } from "react";

export type ReviewReply = { id: string; author: string; body: string };

export type DiffHunk = {
  id: string;
  lineNumber: number;
  kind: "add" | "del" | "context";
  text: string;
  replies: ReviewReply[];
};

export function DiffReviewThread({ hunk }: { hunk: DiffHunk }) {
  const [resolved, setResolved] = useState(false);
  const [collapsed, setCollapsed] = useState(false);
  const [draft, setDraft] = useState("");
  const [replies, setReplies] = useState(hunk.replies);

  const submit = () => {
    const body = draft.trim();
    if (!body) return;
    setReplies((prev) => [
      ...prev,
      { id: String(prev.length + 1), author: "you", body },
    ]);
    setDraft("");
  };

  return (
    <div className="drt-root" data-resolved={resolved}>
      <div className="drt-code" data-kind={hunk.kind}>
        <span className="drt-gutter">{hunk.lineNumber}</span>
        <code className="drt-line">
          <span className="drt-sign" aria-hidden="true">
            {hunk.kind === "add" ? "+" : hunk.kind === "del" ? "-" : " "}
          </span>
          {hunk.text}
        </code>
      </div>

      <div className="drt-thread">
        <header className="drt-thread-head">
          <button type="button" onClick={() => setCollapsed((v) => !v)}>
            {collapsed ? "▸" : "▾"} {replies.length} comment
            {replies.length === 1 ? "" : "s"}
          </button>
          <span className="drt-spacer" />
          <button type="button" onClick={() => setResolved((v) => !v)}>
            {resolved ? "Reopen" : "Resolve"}
          </button>
        </header>

        {collapsed
          ? null
          : replies.map((reply) => (
              <article className="drt-comment" key={reply.id}>
                <strong className="drt-author">{reply.author}</strong>
                <p className="drt-body">{reply.body}</p>
              </article>
            ))}

        {collapsed ? null : (
          <div className="drt-composer">
            <textarea
              value={draft}
              onChange={(e) => setDraft(e.target.value)}
              placeholder="Leave a review comment…"
              aria-label="New review comment"
            />
            <button type="button" onClick={submit} disabled={!draft.trim()}>
              Comment
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

cssRules:
.drt-root {
  border: 1px solid var(--line-subtle, #e4e4e7);
  border-radius: 8px;
  overflow: hidden;
  background: var(--surface-base, #ffffff);
  font-size: 12px;
}
.drt-root[data-resolved="true"] {
  opacity: 0.62;
}
.drt-code {
  display: flex;
  gap: 10px;
  padding: 6px 12px;
  font-family: ui-monospace, SFMono-Regular, monospace;
  border-left: 3px solid transparent;
}
.drt-code[data-kind='add'] {
  background: rgba(34, 197, 94, 0.1);
  border-left-color: #22c55e;
}
.drt-code[data-kind='del'] {
  background: rgba(239, 68, 68, 0.1);
  border-left-color: #ef4444;
}
.drt-gutter {
  width: 34px;
  text-align: right;
  color: var(--text-muted, #a1a1aa);
  user-select: none;
}
.drt-sign {
  margin-right: 6px;
  font-weight: 700;
}
.drt-thread {
  padding: 10px 12px 12px;
  border-top: 1px dashed var(--line-subtle, #e4e4e7);
  background: var(--surface-inset, #fafafa);
}
.drt-thread-head {
  display: flex;
  align-items: center;
  gap: 8px;
}
.drt-thread-head button {
  font: inherit;
  font-size: 11px;
  padding: 2px 6px;
  border-radius: 4px;
  border: 1px solid var(--line-subtle, #e4e4e7);
  background: var(--surface-base, #ffffff);
  color: inherit;
  cursor: pointer;
}
.drt-spacer {
  flex: 1;
}
.drt-comment {
  padding: 8px 0 0;
}
.drt-author {
  display: block;
  font-size: 11px;
  color: var(--text-muted, #71717a);
}
.drt-body {
  margin: 2px 0 0;
  line-height: 1.55;
}
.drt-composer {
  display: flex;
  gap: 8px;
  margin-top: 10px;
}
.drt-composer textarea {
  flex: 1;
  min-height: 48px;
  padding: 6px 8px;
  font: inherit;
  resize: vertical;
  border-radius: 6px;
  border: 1px solid var(--line-subtle, #e4e4e7);
  background: var(--surface-base, #ffffff);
  color: inherit;
}
.drt-composer button {
  align-self: flex-start;
  padding: 6px 12px;
  font: inherit;
  border-radius: 6px;
  border: none;
  background: var(--accent, #18181b);
  color: #ffffff;
  cursor: pointer;
}
.drt-composer button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
